$('#plan').onclick=async()=>{if(!db)return;if(!origin){$('#journeys').innerHTML='<div class="empty">Enable location or use Correct location on the Stops tab.</div>';return}if(!destination){$('#journeys').innerHTML='<div class="empty">Choose a search result or tap the destination map.</div>';return}clearJourneyMap();let version=++planVersion;$('#plan').disabled=true;$('#journeys').innerHTML='<p class="notice">Comparing walking, waiting and transfers…</p>';await refresh();await new Promise(r=>setTimeout(r,25));try{let now=Date.now(),results=planJourney(db,rt,origin,destination,now);if(version!==planVersion)return;journeyResults=results;$('#journeys').innerHTML=results.length?`<p class="notice">Compared at ${clock(now)} · fastest arrival first · tap Find fastest journey now to refresh the options.</p>`+results.map((r,i)=>journeyCard(r,i,now)).join(''):'<div class="empty">No journey found within the next 4 hours, with up to two transfers and stops within 800 m of each endpoint. Try a nearby point.</div>';if(results.length)showJourney(0);}catch(e){$('#journeys').innerHTML='<div class="empty">Could not calculate this journey. Try again.</div>';console.error(e)}finally{$('#plan').disabled=false}};
function showJourney(index){
 const result=journeyResults[index];if(!result)return;
 const wrap=$('#journey-route-wrap');wrap.hidden=false;$('#journey-route-title').textContent=index===0?'Fastest journey':'Alternative journey '+index;
 if(journeyMap){journeyMap.remove();journeyMap=null;}journeyMarkers=[];
 journeyMap=newMap('journey-route-map',origin||draft);if(!journeyMap)return;
 journeyMap.on('load',()=>{
  const features=[],all=[],legend=[];
  result.legs.forEach((leg,i)=>{
   let points=[],approximate=false,color=leg.type==='bus'?routeColor(leg.route.route_id):'#728595';
   if(leg.type==='bus'){
    const trip=db.trips.get(leg.tripId),times=db.times.get(leg.tripId)||[];
    let board=times.findIndex(s=>s.seq===leg.boardSeq);if(board<0)board=times.findIndex(s=>s.stop_id===leg.from.id);
    let end=times.findIndex((s,j)=>j>board&&(leg.endSeq!=null?s.seq===leg.endSeq:s.stop_id===leg.to.id));
    const pattern=boardingNetwork(db,leg.from.id).patterns.find(p=>p.tripIds.has(leg.tripId)&&p.downstream[0].seq===times[board]?.seq);
    if(pattern){const shape=pattern.points;let last=0;for(const call of times.slice(board,end+1)){const stop=stopIndex.get(call.stop_id);let best=Infinity,at=last;for(let j=last;j<shape.length;j++){let d=distance(stop,{lon:shape[j][0],lat:shape[j][1]});if(d<best){best=d;at=j;}}last=at;}points=shape.slice(0,last+1);approximate=pattern.approximate;}
    if(points.length<2){points=times.slice(board,end+1).map(s=>stopIndex.get(s.stop_id)).filter(Boolean).map(coords);approximate=true;}
    if(points.length<2){points=[coords(leg.from),coords(leg.to)];approximate=true;}
    legend.push(`Bus ${line(leg.route)}: ${name(leg.from)} → ${name(leg.to)}${approximate?' · stop outline':''}`);
    addJourneyMarker(leg.from,`Board ${line(leg.route)} · ${name(leg.from)}`,color);addJourneyMarker(leg.to,`Get off ${line(leg.route)} · ${name(leg.to)}`,color);
   }else{points=[coords(leg.from),coords(leg.to)];legend.push(`${leg.type==='transfer'?'Change buses':'Walk'}: ${name(leg.from)||'Your location'} → ${name(leg.to)||'Destination'} · walking connection is approximate`);if(leg.type==='transfer')addJourneyMarker(leg.to,'Change buses here · '+name(leg.to),'#cf3b79');}
   all.push(...points);features.push({type:'Feature',geometry:{type:'LineString',coordinates:points},properties:{color,walk:leg.type!=='bus'}});
  });
  journeyMap.addSource('journey-path',{type:'geojson',data:fc(features)});
  journeyMap.addLayer({id:'journey-bus-path',type:'line',source:'journey-path',filter:['==',['get','walk'],false],paint:{'line-color':['get','color'],'line-width':5},layout:{'line-cap':'round','line-join':'round'}});
  journeyMap.addLayer({id:'journey-walking-path',type:'line',source:'journey-path',filter:['==',['get','walk'],true],paint:{'line-color':'#728595','line-width':3,'line-dasharray':[2,2]}});
  $('#journey-route-legend').innerHTML=legend.map(x=>'<p>'+esc(x)+'</p>').join('');
  if(all.length){let bounds=new maplibregl.LngLatBounds(all[0],all[0]);all.forEach(p=>bounds.extend(p));journeyMap.fitBounds(bounds,{padding:45,maxZoom:16,duration:0});}
 });
 wrap.scrollIntoView?.({behavior:'smooth',block:'start'});
}
function addJourneyMarker(stop,label,color){let element=document.createElement('button');element.className='journey-stop-marker';element.style.background=color;element.textContent='•';element.setAttribute('aria-label',label);let m=new maplibregl.Marker({element}).setLngLat(coords(stop)).setPopup(new maplibregl.Popup({offset:12}).setHTML(esc(label))).addTo(journeyMap);journeyMarkers.push(m);}

function journeyCard(r,i,now){let buses=r.legs.filter(l=>l.type==='bus'),previous=now;let steps=r.legs.map(l=>{let wait=l.type==='bus'?Math.max(0,Math.round((l.start-previous)/60000)):0;previous=l.end;if(l.type==='bus')return `<li><div class="legheading"><span class="chip">${esc(line(l.route))}</span> To ${esc(name(l.headsign))}</div>${wait?`Wait ~${wait} min · `:''}Board ${clock(l.start)} at ${esc(name(l.from))}<br>Get off at ${esc(name(l.to))} · ~${clock(l.end)}<br><small>${l.stops} stops · ${l.live?'Live departure':'Scheduled departure'} · ${l.arrivalLive?'live arrival estimate':'arrival estimated from timetable'}</small></li>`;if(l.type==='transfer')return `<li><div class="legheading">Change buses${l.from?.id!==l.to?.id?' at '+esc(name(l.to)):''}</div><small>Walk ~${Math.round(l.meters*1.3)} m + 2 min connection buffer</small></li>`;return `<li><div class="legheading">Walk ~${Math.round(l.meters*1.3)} m · ${Math.round((l.end-l.start)/60000)} min</div><small>${l.to?.stop_id?'To '+esc(name(l.to)):'To your destination'} · estimated walking distance</small></li>`});return `<article class="journeycard"><div class="journey-top"><span class="bestlabel">${i===0?'FASTEST ARRIVAL':'ALTERNATIVE'} · ${buses.length?buses.length-1+' TRANSFERS':'WALK ONLY'}</span><span class="duration">${Math.ceil((r.arrival-now)/60000)} min</span></div><h2>Arrive ~${clock(r.arrival)}</h2><button class="secondary journey-show" data-journey="${i}">Show route and transfers</button><ol class="timeline">${steps.join('')}</ol></article>`}
