 const watchedStop=stopId,arrivals=departures(db,rt,stopId,Date.now(),1000),near=lastAccuracy<=60&&!!origin&&Date.now()-lastLocation<20000&&distance(origin,stopIndex.get(stopId))<150;
 const prompt=passengerReports.tick(arrivals,near);if(prompt){$('#passenger-prompt').hidden=false;$('#passenger-question').textContent='Did bus '+line(prompt.arrival.route)+' arrive at '+name(stopIndex.get(stopId))+'?';$('#passenger-time').textContent='Optional · closes in 20 seconds';clearTimeout(reportTimer);reportTimer=setTimeout(()=>{passengerReports.dismiss();$('#passenger-prompt').hidden=true;},Math.max(0,prompt.until-Date.now()));}
